package sqlstore

// sqliteQueries are the stores' statements for SQLite. A transaction
// starts with BEGIN IMMEDIATE, taking the database's write lock up
// front, so a SELECT in it needs no FOR UPDATE.
var sqliteQueries = queries{ //nolint:gosec // G101: field names such as keyGet are statements, not credentials
	nonceInsert:              "INSERT INTO oid4vc_issuer_nonces (id, owner, sweep_after, record) VALUES (?, ?, ?, ?)",
	nonceSpend:               "INSERT INTO oid4vc_issuer_nonces (id, owner, sweep_after, record) VALUES (?, ?, ?, ?) ON CONFLICT (id) DO NOTHING",
	nonceConsumeOwned:        "DELETE FROM oid4vc_issuer_nonces WHERE id = ? AND owner = ? RETURNING record",
	nonceSweep:               "DELETE FROM oid4vc_issuer_nonces WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_issuer_nonces WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	pacInsert:                "INSERT INTO oid4vc_issuer_pre_authorized_codes (id, owner, sweep_after, record, tx_code_hash) VALUES (?, ?, ?, ?, ?)",
	pacSelectForConsume:      "SELECT tx_code_hash, wrong_attempts, record FROM oid4vc_issuer_pre_authorized_codes WHERE id = ?",
	pacSetAttempts:           "UPDATE oid4vc_issuer_pre_authorized_codes SET wrong_attempts = ? WHERE id = ?",
	pacDelete:                "DELETE FROM oid4vc_issuer_pre_authorized_codes WHERE id = ?",
	pacSweep:                 "DELETE FROM oid4vc_issuer_pre_authorized_codes WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_issuer_pre_authorized_codes WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	deferredTxInsert:         "INSERT INTO oid4vc_issuer_deferred_transactions (id, owner, sweep_after, record) VALUES (?, ?, ?, ?)",
	deferredTxGet:            "SELECT record FROM oid4vc_issuer_deferred_transactions WHERE id = ?",
	deferredTxGetForUpdate:   "SELECT record FROM oid4vc_issuer_deferred_transactions WHERE id = ?",
	deferredTxUpdate:         "UPDATE oid4vc_issuer_deferred_transactions SET owner = ?, sweep_after = ?, record = ? WHERE id = ?",
	deferredTxDelete:         "DELETE FROM oid4vc_issuer_deferred_transactions WHERE id = ?",
	deferredTxSweep:          "DELETE FROM oid4vc_issuer_deferred_transactions WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_issuer_deferred_transactions WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	notificationInsert:       "INSERT INTO oid4vc_issuer_notifications (id, owner, sweep_after, record) VALUES (?, ?, ?, ?)",
	notificationGet:          "SELECT record FROM oid4vc_issuer_notifications WHERE id = ?",
	notificationSweep:        "DELETE FROM oid4vc_issuer_notifications WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_issuer_notifications WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	offerInsert:              "INSERT INTO oid4vc_issuer_credential_offers (id, owner, sweep_after, record) VALUES (?, ?, ?, ?)",
	offerGet:                 "SELECT record FROM oid4vc_issuer_credential_offers WHERE id = ?",
	offerSweep:               "DELETE FROM oid4vc_issuer_credential_offers WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_issuer_credential_offers WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	txInsert:                 "INSERT INTO oid4vc_verifier_transactions (id, owner, sweep_after, record, key_id, response_code_hash) VALUES (?, ?, ?, ?, ?, ?)",
	txGet:                    "SELECT record FROM oid4vc_verifier_transactions WHERE id = ?",
	txGetForUpdate:           "SELECT record FROM oid4vc_verifier_transactions WHERE id = ?",
	txUpdate:                 "UPDATE oid4vc_verifier_transactions SET owner = ?, sweep_after = ?, record = ?, key_id = ?, response_code_hash = ? WHERE id = ?",
	txIDByKeyID:              "SELECT id FROM oid4vc_verifier_transactions WHERE key_id = ? AND key_id <> ''",
	txIDByResponseCode:       "SELECT id FROM oid4vc_verifier_transactions WHERE response_code_hash = ? AND response_code_hash <> ''",
	txSweep:                  "DELETE FROM oid4vc_verifier_transactions WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_verifier_transactions WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	credentialUpsert:         "INSERT INTO oid4vc_wallet_credentials (id, owner, sweep_after, record) VALUES (?, ?, ?, ?) ON CONFLICT (id) DO UPDATE SET owner = excluded.owner, sweep_after = excluded.sweep_after, record = excluded.record",
	credentialGet:            "SELECT record FROM oid4vc_wallet_credentials WHERE id = ?",
	credentialGetForUpdate:   "SELECT record FROM oid4vc_wallet_credentials WHERE id = ?",
	credentialUpdate:         "UPDATE oid4vc_wallet_credentials SET owner = ?, sweep_after = ?, record = ? WHERE id = ?",
	credentialList:           "SELECT id, record FROM oid4vc_wallet_credentials ORDER BY id",
	credentialDelete:         "DELETE FROM oid4vc_wallet_credentials WHERE id = ?",
	authorizationUpsert:      "INSERT INTO oid4vc_wallet_authorizations (id, owner, sweep_after, record) VALUES (?, ?, ?, ?) ON CONFLICT (id) DO UPDATE SET owner = excluded.owner, sweep_after = excluded.sweep_after, record = excluded.record",
	authorizationGet:         "SELECT record FROM oid4vc_wallet_authorizations WHERE id = ?",
	authorizationConsume:     "DELETE FROM oid4vc_wallet_authorizations WHERE id = ? RETURNING record",
	authorizationList:        "SELECT id, record FROM oid4vc_wallet_authorizations ORDER BY id",
	authorizationDelete:      "DELETE FROM oid4vc_wallet_authorizations WHERE id = ?",
	grantUpsert:              "INSERT INTO oid4vc_wallet_grants (id, owner, sweep_after, record) VALUES (?, ?, ?, ?) ON CONFLICT (id) DO UPDATE SET owner = excluded.owner, sweep_after = excluded.sweep_after, record = excluded.record",
	grantGet:                 "SELECT record FROM oid4vc_wallet_grants WHERE id = ?",
	grantGetForUpdate:        "SELECT record FROM oid4vc_wallet_grants WHERE id = ?",
	grantUpdate:              "UPDATE oid4vc_wallet_grants SET owner = ?, sweep_after = ?, record = ? WHERE id = ?",
	grantList:                "SELECT id, record FROM oid4vc_wallet_grants ORDER BY id",
	grantDelete:              "DELETE FROM oid4vc_wallet_grants WHERE id = ?",
	deferredUpsert:           "INSERT INTO oid4vc_wallet_deferred (id, owner, sweep_after, record) VALUES (?, ?, ?, ?) ON CONFLICT (id) DO UPDATE SET owner = excluded.owner, sweep_after = excluded.sweep_after, record = excluded.record",
	deferredList:             "SELECT id, record FROM oid4vc_wallet_deferred ORDER BY id",
	deferredDelete:           "DELETE FROM oid4vc_wallet_deferred WHERE id = ?",
	keyInsert:                "INSERT INTO oid4vc_wallet_keys (id, owner, sweep_after, record) VALUES (?, ?, ?, ?)",
	keyGet:                   "SELECT record FROM oid4vc_wallet_keys WHERE id = ?",
	keyDelete:                "DELETE FROM oid4vc_wallet_keys WHERE id = ?",
	statusIndexReserve:       "INSERT INTO oid4vc_status_indices (uri, idx) VALUES (?, ?) ON CONFLICT (uri, idx) DO NOTHING",
	statusIndexCount:         "SELECT CAST(COALESCE(SUM(reserved), 0) AS BIGINT) FROM oid4vc_status_list_count_shards WHERE uri = ?",
	statusIndexSet:           "UPDATE oid4vc_status_indices SET status = ? WHERE uri = ? AND idx = ?",
	statusIndexGet:           "SELECT status FROM oid4vc_status_indices WHERE uri = ? AND idx = ?",
	statusIndexList:          "SELECT idx, status FROM oid4vc_status_indices WHERE uri = ? AND status <> 0 UNION ALL SELECT idx, status FROM oid4vc_status_indices WHERE uri = ? AND idx >= ? AND status = 0",
	statusIndexDeleteBatch:   "DELETE FROM oid4vc_status_indices WHERE uri = ? AND idx IN (SELECT idx FROM oid4vc_status_indices WHERE uri = ? ORDER BY idx LIMIT ?)",
	statusIndexDeleteCount:   "DELETE FROM oid4vc_status_list_count_shards WHERE uri = ?",
	statusIndexDeleteVersion: "DELETE FROM oid4vc_status_list_versions WHERE uri = ?",
	statusIndexDeleteTokens:  "DELETE FROM oid4vc_status_list_tokens WHERE uri = ?",
	statusTokenHead:          "SELECT COALESCE((SELECT version FROM oid4vc_status_list_versions WHERE uri = ?), 0), t.version, t.signed_at, t.exp, t.signer FROM (SELECT 1) AS one LEFT JOIN oid4vc_status_list_tokens t ON t.uri = ? AND t.form = ? AND t.token IS NOT NULL",
	statusTokenGet:           "SELECT token, version, signed_at, exp, signer FROM oid4vc_status_list_tokens WHERE uri = ? AND form = ? AND token IS NOT NULL",
	statusTokenClaim:         "INSERT INTO oid4vc_status_list_tokens (uri, form, lease_holder, lease_until) VALUES (?, ?, ?, ?) ON CONFLICT (uri, form) DO UPDATE SET lease_holder = excluded.lease_holder, lease_until = excluded.lease_until WHERE oid4vc_status_list_tokens.lease_holder IS NULL OR oid4vc_status_list_tokens.lease_until <= ? OR oid4vc_status_list_tokens.lease_holder = excluded.lease_holder",
	statusTokenPut:           "INSERT INTO oid4vc_status_list_tokens (uri, form, token, version, signed_at, exp, signer) VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT (uri, form) DO UPDATE SET token = excluded.token, version = excluded.version, signed_at = excluded.signed_at, exp = excluded.exp, signer = excluded.signer WHERE oid4vc_status_list_tokens.token IS NULL OR oid4vc_status_list_tokens.version < excluded.version OR (oid4vc_status_list_tokens.version = excluded.version AND oid4vc_status_list_tokens.signed_at < excluded.signed_at)",
	statusTokenRelease:       "UPDATE oid4vc_status_list_tokens SET lease_holder = NULL, lease_until = 0 WHERE uri = ? AND form = ? AND lease_holder = ?",
	wpInstanceInsert:         "INSERT INTO oid4vc_walletprovider_instances (id, owner, sweep_after, record, key_thumbprint, revision, credential_id) VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT DO NOTHING",
	wpInstanceGet:            "SELECT record FROM oid4vc_walletprovider_instances WHERE id = ?",
	wpInstanceUpdate:         "UPDATE oid4vc_walletprovider_instances SET sweep_after = ?, record = ?, revision = ? WHERE id = ? AND revision = ? AND key_thumbprint = ?",
	wpInstanceRevision:       "SELECT revision, key_thumbprint FROM oid4vc_walletprovider_instances WHERE id = ?",
	wpInstanceList:           "SELECT id, record FROM oid4vc_walletprovider_instances WHERE id > ? ORDER BY id LIMIT ?",
	wpInstanceKeyInsert:      "INSERT INTO oid4vc_walletprovider_instance_keys (id, owner, sweep_after, record, instance_id, revision) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT (id) DO NOTHING",
	wpInstanceKeyGet:         "SELECT record FROM oid4vc_walletprovider_instance_keys WHERE id = ?",
	wpInstanceKeyUpdate:      "UPDATE oid4vc_walletprovider_instance_keys SET sweep_after = ?, record = ?, revision = ? WHERE id = ? AND revision = ? AND instance_id = ?",
	wpInstanceKeyRevision:    "SELECT revision, instance_id FROM oid4vc_walletprovider_instance_keys WHERE id = ?",
	wpInstanceKeyList:        "SELECT id, record FROM oid4vc_walletprovider_instance_keys WHERE instance_id = ? AND id > ? ORDER BY id LIMIT ?",
	wpInstanceKeyNoRetain:    "SELECT id, record FROM oid4vc_walletprovider_instance_keys WHERE sweep_after IS NULL AND id > ? ORDER BY id LIMIT ?",
	wpInstanceKeySweep:       "DELETE FROM oid4vc_walletprovider_instance_keys WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_walletprovider_instance_keys WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	wpChallengeInsert:        "INSERT INTO oid4vc_walletprovider_challenges (id, owner, sweep_after, record) VALUES (?, ?, ?, ?) ON CONFLICT (id) DO NOTHING",
	wpChallengeConsume:       "DELETE FROM oid4vc_walletprovider_challenges WHERE id = ? RETURNING record",
	wpChallengeSweep:         "DELETE FROM oid4vc_walletprovider_challenges WHERE sweep_after < ? AND sweep_after <= COALESCE((SELECT sweep_after FROM oid4vc_walletprovider_challenges WHERE sweep_after < ? ORDER BY sweep_after LIMIT 1 OFFSET ?), ?)",
	migrationsCreate:         "CREATE TABLE IF NOT EXISTS oid4vc_schema_migrations (version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at BIGINT NOT NULL)",
	migrationApplied:         "SELECT 1 FROM oid4vc_schema_migrations WHERE version = ?",
	migrationRecord:          "INSERT INTO oid4vc_schema_migrations (version, name, applied_at) VALUES (?, ?, ?)",
	migrationVersions:        "SELECT version FROM oid4vc_schema_migrations",
}

// The statements of a SQLite write transaction (DB.write).
const (
	// sqliteBusyTimeout has a connection wait up to 10 seconds for
	// another's write lock before failing.
	sqliteBusyTimeout = "PRAGMA busy_timeout = 10000"
	sqliteBegin       = "BEGIN IMMEDIATE"
	sqliteCommit      = "COMMIT"
	sqliteRollback    = "ROLLBACK"
)
